export function dispatchViewportPointerShortcut(event,model,{running=false,navigating=false,dialog=false,activate,dispatch,error}={}){if(event.type!=='pointerdown'||event.pointerType&&event.pointerType!=='mouse'||event.isPrimary===false||event.defaultPrevented||running||navigating||!Number.isInteger(event.button)||event.button<0||event.button>4)return false;const button=[1,4,2,8,16][event.button];if(event.buttons&&event.buttons!==button)return false;const result=model.resolve(event,{scope:'viewport',running,dialog,editing:false,navigating:false});if(!result.command)return false;event.preventDefault();event.stopImmediatePropagation();try{activate?.();dispatch?.(result.command,event);}catch(e){error?.(e.message);}return true;}
export const viewportPointerShortcutContract=Object.freeze({profile:'Existing version1 shortcut profiles; keyboard keys preserved, Mouse1..Mouse5 with optional Primary/Shift/Alt modifiers. Mouse1=left, Mouse2=middle, Mouse3=right, Mouse4=back, Mouse5=forward.',authoring:'Only viewport-eligible commands accept mouse bindings. Record while a shortcut slot is focused; conflict/override/reset/import/export/revision use the same profile validator. Explicit assignments only; no new default pointer binding.',execution:'Stopped scene/extra viewport canvas pointerdown, owner-window dialog guard and viewport activation. Assigned commands consume the event before camera/selection; unassigned input follows existing navigation. Existing gesture and touch/pen are preserved.',limits:'Discrete editor commands only, not continuous camera gesture/action-axis remapping. No background OS/global mouse hook or game/mobile input changes.'});
